corrected_code:
export const subscriptionRouter = router({
  adjustSeats: protectedProcedure
    .input(z.object({ subscriptionId: z.string(), seatCount: z.number().min(1) }))
    .mutation(async ({ input, ctx }) => {
      const sub = await ctx.em.findOne(SubscriptionEntity, {
        id: input.subscriptionId,
        tenantId: ctx.user.tenantId,
      });
      if (!sub) throw new TRPCError({ code: 'FORBIDDEN', message: 'Unauthorized subscription modification' });
      sub.allocatedSeats = input.seatCount;
      await ctx.em.flush();
      return { subscriptionId: sub.id, allocatedSeats: sub.allocatedSeats };
    }),
});
